package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.access.SettingRepository;
import net.officefloor.hq.app.period.Period;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.sheet.SheetRepository;

/** How a claim opened on a sheet now is numbered. */
public final class ClaimNumbering {

    private ClaimNumbering() {
    }

    /**
     * The number a claim due by {@code dueBy} takes when opened on the sheet now: while the sheet numbers by period
     * and its today is on or after that setting's date, the next within the claim's period (by its due-by) as
     * {@code <period name>-<n>}, or {@code X-<n>} in no period; otherwise the sheet's next.
     */
    public static String number(String sheetId, LocalDate dueBy, ClaimRepository repository,
            SettingRepository settings, SheetRepository sheets, PeriodRepository periods) {
        LocalDate from = settings.periodNumberingFrom(sheetId);
        if (from == null || sheets.today(sheetId).isBefore(from)) {
            return String.valueOf(repository.nextNumber(sheetId));
        }
        Period period = periods.on(sheetId, dueBy);
        return period == null ? "X-" + repository.nextNumber(sheetId, "X")
                : period.name() + "-" + repository.nextNumber(sheetId, String.valueOf(period.id()));
    }
}
    }

    /** The number of the sheet's last bulk settle batch; null when there has been none. */
    public Integer lastSettleBatch(String sheetId) {
        return jdbc.query("SELECT last_settle_batch FROM sheet WHERE id = ?",
                rs -> rs.next() && rs.getInt(1) > 0 ? rs.getInt(1) : null, sheetId);
    }

    /** Mark the claim settled by the bulk settle batch. */
    public void markSettleBatch(Claim claim, int batch) {
        jdbc.update("UPDATE claim SET settle_batch = ? WHERE id = ?", batch, claim.getId());
        claim.setSettleBatch(batch);
    }

    /**
     * Take the next claim number of the sheet's tree (its top ancestor and everything below it, the sheets sharing one
     * sequence): one after the last number given on any of its sheets, kept as this sheet's last. The tree's sheets
     * are locked first so two users never get the same one.
     */
    public int nextNumber(String sheetId) {
        List<String> tree = treeOf(sheetId);
        String in = String.join(",", java.util.Collections.nCopies(tree.size(), "?"));
        List<Integer> last = jdbc.queryForList("SELECT last_claim_number FROM sheet WHERE id IN (" + in + ")"
                + " ORDER BY id FOR UPDATE", Integer.class, tree.toArray());
        int next = last.stream().mapToInt(Integer::intValue).max().orElse(0) + 1;
        jdbc.update("UPDATE sheet SET last_claim_number = ? WHERE id = ?", next, sheetId);
        return next;
    }

    /** The sheet's tree: its top ancestor (following parents up), then all the sheets below that, each once. */
    private List<String> treeOf(String sheetId) {
        java.util.Set<String> up = new java.util.LinkedHashSet<>();
        String root = sheetId;
        while (up.add(root)) {
            String parent = jdbc.query("SELECT setting_value FROM sheet_setting WHERE sheet_id = ? AND setting_key = 'parent'",
                    (rs, n) -> rs.getString(1), root).stream().filter(v -> v != null && !v.isBlank()).findFirst().orElse(null);
            if (parent == null) {
                break;
            }
            root = parent;
        }
        java.util.Set<String> tree = new java.util.LinkedHashSet<>(List.of(root));
        java.util.Deque<String> todo = new java.util.ArrayDeque<>(List.of(root));
        while (!todo.isEmpty()) {
            for (String child : jdbc.query("SELECT sheet_id FROM sheet_setting WHERE setting_key = 'parent' AND setting_value = ?",
                    (rs, n) -> rs.getString(1), todo.poll())) {
                if (tree.add(child)) {
                    todo.add(child);
                }
            }
        }
        tree.add(sheetId); // under a parent cycle, the walk down may not reach it
        return List.copyOf(tree);
    }

    /** Take the next number of one of the sheet's per-period sequences (a period's id, or X for no period), from 1. */
    public int nextNumber(String sheetId, String sequence) {
        try {
            jdbc.update("INSERT INTO claim_sequence (sheet_id, seq_key) SELECT ?, ? FROM DUAL WHERE NOT EXISTS"
